    11→public class MutationTestSummaryData {
    12→
    13→  private final String                     fileName;
    14→  private final Collection<MutationResult> mutations = new ArrayList<>();
    15→  private final Set<ClassInfo>             classes   = new HashSet<>();
    16→
    17→  public MutationTestSummaryData(final String fileName,
    18→      final Collection<MutationResult> results, final Collection<ClassInfo> classes) {
    19→    this.fileName = fileName;
    20→    this.mutations.addAll(results);
    21→    this.classes.addAll(classes);
    22→  }
    23→
    24→  public String getPackageName() {
    25→    // Name needs to be in slashes instead of dots for mutation-testing-elements
    26→    final String packageName = this.classes.iterator().next().getName()
    27→        .asJavaName().replace(".", "/");
    28→    final int lastSlash = packageName.lastIndexOf('/');
    29→    return lastSlash > 0 ? packageName.substring(0, lastSlash) : "default";
    30→  }
    31→
    32→  public void addTestSummary(final MutationTestSummaryData data) {
    33→    this.mutations.addAll(data.mutations);
    34→    this.classes.addAll(data.classes);
    35→  }
    36→
    37→  public String getFileName() {
    38→    return this.fileName;
    39→  }
    40→
    41→  public Collection<MutationResult> getResults() {
    42→    return this.mutations;
    43→  }
    44→
    45→  public Collection<ClassInfo> getClasses() {
